/*
 * Frontier Showdown service worker, generated by `npm run build` (tools/build.mjs).
 *
 * - The app shell (HTML, JS modules, CSS, fonts, menu art) is precached per build in
 *   `fs-shell-<version>`; older shell caches are deleted when a new build activates.
 * - Fighter, stage, audio and portrait files are cached on first use in `fs-assets`. Their
 *   URLs carry `?v=<content hash>` from manifest.json, so a changed file gets a new URL and a
 *   file that did not change is never downloaded again. Entries that no longer appear in the
 *   manifest are pruned on activation.
 * - Navigations and manifest.json go to the network first, so a new deploy is seen on the
 *   next visit, and fall back to the cache offline.
 */
const VERSION = "__VERSION__";
const PRECACHE = __PRECACHE__;
const SHELL = `fs-shell-${VERSION}`;
const ASSETS = "fs-assets";
const SCOPE = new URL(self.registration.scope);
const shellUrls = new Set(PRECACHE.map((p) => new URL(p, SCOPE).href));

async function put(cacheName, request, response) {
  try {
    const cache = await caches.open(cacheName);
    await cache.put(request, response);
  } catch {
    // Quota exceeded or storage unavailable: keep serving from the network.
  }
}

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL).catch(() => null);
    if (cache) {
      await Promise.all(PRECACHE.map(async (path) => {
        try {
          const res = await fetch(new Request(new URL(path, SCOPE), { cache: "reload" }));
          if (res.ok) await cache.put(new URL(path, SCOPE).href, res);
        } catch {
          // A missing shell file only costs offline support for that file.
        }
      }));
    }
    await self.skipWaiting();
  })());
});

async function pruneAssets() {
  let hashes = null;
  try {
    const res = await fetch(new URL("manifest.json", SCOPE), { cache: "no-cache" });
    if (res.ok) {
      await put(SHELL, new URL("manifest.json", SCOPE).href, res.clone());
      hashes = (await res.json()).hashes;
    }
  } catch {
    return;
  }
  if (!hashes) return;
  const keep = new Set(Object.entries(hashes).map(([path, h]) => {
    const url = new URL(path, SCOPE);
    url.searchParams.set("v", h);
    return url.href;
  }));
  const cache = await caches.open(ASSETS);
  for (const req of await cache.keys()) if (!keep.has(req.url)) await cache.delete(req);
}

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith("fs-shell-") && name !== SHELL) await caches.delete(name);
    }
    await pruneAssets().catch(() => {});
    await self.clients.claim();
  })());
});

async function networkFirst(request, cacheKey, timeoutMs = 4000) {
  try {
    const res = await Promise.race([
      fetch(request),
      new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), timeoutMs)),
    ]);
    if (res.ok) put(SHELL, cacheKey, res.clone());
    return res;
  } catch (error) {
    const cached = await caches.match(cacheKey);
    if (cached) return cached;
    throw error;
  }
}

async function cacheFirst(request, cacheName) {
  const cached = await caches.match(request, { cacheName });
  if (cached) return cached;
  const res = await fetch(request);
  if (res.ok && res.type === "basic") put(cacheName, request, res.clone());
  return res;
}

async function staleWhileRevalidate(request, cacheName) {
  const cached = await caches.match(request, { cacheName });
  const fresh = fetch(request).then((res) => {
    if (res.ok && res.type === "basic") put(cacheName, request, res.clone());
    return res;
  });
  return cached || fresh;
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET" || request.headers.has("range")) return;
  const url = new URL(request.url);
  if (url.origin !== SCOPE.origin || !url.pathname.startsWith(SCOPE.pathname)) return;
  const path = url.pathname.slice(SCOPE.pathname.length);

  if (request.mode === "navigate") {
    event.respondWith(networkFirst(request, new URL("index.html", SCOPE).href));
    return;
  }
  if (path === "manifest.json") {
    event.respondWith(networkFirst(request, url.href));
    return;
  }
  if (shellUrls.has(url.href)) {
    event.respondWith(caches.match(url.href, { cacheName: SHELL }).then((hit) => hit || fetch(request)));
    return;
  }
  if (path.startsWith("assets/")) {
    event.respondWith(url.searchParams.has("v") ? cacheFirst(request, ASSETS) : staleWhileRevalidate(request, ASSETS));
  }
});

self.addEventListener("message", (event) => {
  if (event.data === "version") event.source?.postMessage({ type: "version", version: VERSION });
});
